python3 -c "import pandas as pd; import numpy as np; train = pd.read_csv('train.csv'); test = pd.read_csv('test.csv'); X_train = train.drop(columns=['target']).values; y_train = train['target'].values; X_mean = np.mean(X_train, axis=0); X_std = np.std(X_train, axis=0); X_std[X_std == 0] = 1.0; X_train_scaled = (X_train - X_mean) / X_std; X_train_bias = np.c_[np.ones(X_train_scaled.shape[0]), X_train_scaled]; XtX = X_train_bias.T @ X_train_bias; Xty = X_train_bias.T @ y_train; alphas = np.logspace(-3, 5, 100); best_alpha = 1.0; best_score = float('inf'); p = X_train_bias.shape[1]; 
for a in alphas:
    I = np.eye(p); I[0, 0] = 0;
    try:
        theta = np.linalg.solve(XtX + a * I, Xty)
        inv_part = np.linalg.inv(XtX + a * I)
        h_ii = np.sum((X_train_bias @ inv_part) * X_train_bias, axis=1)
        y_pred_train = X_train_bias @ theta
        errors = (y_train - y_pred_train) / (1 - h_ii)
        loocv_rmse = np.sqrt(np.mean(errors**2))
        if loocv_rmse < best_score:
            best_score = loocv_rmse
            best_alpha = a
    except: continue
