python3 -c "import pandas as pd; import numpy as np; train = pd.read_csv('train.csv'); X_train = train.drop(columns=['target']).values; y_train = train['target'].values; X_mean = np.mean(X_train, axis=0); X_std = np.std(X_train, axis=0); X_std[X_std == 0] = 1.0; X_train_scaled = (X_train - X_mean) / X_std; X_train_bias = np.c_[np.ones(X_train_scaled.shape[0]), X_train_scaled]; train['target_rounded'] = train['target'].round(6); unique_targets = train['target_rounded'].unique(); alphas = np.logspace(-3, 5, 100); best_alpha = 1.0; best_score = float('inf'); p = X_train_bias.shape[1];
for a in alphas:
    group_errors = []
    for target_val in unique_targets:
        mask_val = (train['target_rounded'] == target_val)
        X_tr = X_train_bias[~mask_val]; y_tr = y_train[~mask_val]; X_val = X_train_bias[mask_val]; y_val = y_train[mask_val];
        I = np.eye(p); I[0, 0] = 0;
        try:
            theta = np.linalg.solve(X_tr.T @ X_tr + a * I, X_tr.T @ y_tr)
            y_pred_val = X_val @ theta; group_errors.extend(y_val - y_pred_val)
        except: continue
    if group_errors:
        rmse = np.sqrt(np.mean(np.array(group_errors)**2))
        if rmse < best_score: best_score = rmse; best_alpha = a
print(best_alpha)"
